;****************************************************************;* Filename: HDBOOT4/ASM					*;****************************************************************;* TRS-80 Model 4 hard disk loader for LS-DOS			*;****************************************************************;;	The Model 4P boot ROM, and the FreHD auto boot ROM on a Model 4,;	read cylinder 0, head 0, sector 1 of the hard disk (256 bytes);	into 4300H and jump to it.;;	Sectors of cylinder 0, counted from head 0 sector 0 on through;	the heads (32 per head):;	0	unused;	1	this loader (byte 2 holds the directory cylinder, as in a;		floppy boot sector, where LS-DOS looks when it gets lost);	2-37	memory 0000H-23FFH: BOOT/SYS (lowcore) with SYS0 on top;	38-45	video memory F800H-FFFFH (the LS-DOS logo);;	The loader does what the floppy BOOT/SYS does before it starts;	SYS0: memory map, CRTC, the disk interrupt hooks. There are no;	CALLs: on a 4P a call in page 0 can bring the boot ROM back in.;;	Built by zmac-build/build.py with all lowcore symbols: XREF;	(EQU,LIMIT) leaves some it needs out of LOWCORE/EQU.;*GET	LOWCORE/EQU;	ORG	4300HBOOT	NOP	CP	HDDIR		;Directory cylinder	DI	LD	A,18H		;Reset the hard disk controller	OUT	(0C1H),A	LD	A,86H		;80x24, RAM, video at F800H	OUT	(84H),A	LD	A,50H		;Fast, external I/O bus on	OUT	(0ECH),A	LD	A,0CH		;Controller enable, wait states	OUT	(0C1H),ABRDY	IN	A,(0CFH)	;Wait until ready and not busy	AND	0C0H	CP	40H	JR	NZ,BRDY;;	Load sector E of head D (from head 0 sector 2) to HL, on until;	HL wraps round past FFFFH, going from 2400H to F800H;	LD	HL,0000H	LD	DE,0002HBNEXT	LD	A,D	OR	80H		;256 byte sectors, drive 0	OUT	(0CEH),A	LD	A,E	OUT	(0CBH),A	XOR	A	OUT	(0CCH),A	;Cylinder 0	OUT	(0CDH),A	INC	A	OUT	(0CAH),A	;One sector	LD	A,20H		;Read sector	OUT	(0CFH),ABWAIT	IN	A,(0CFH)	RLCA			;Busy?	JR	C,BWAIT	IN	A,(0CFH)	AND	09H		;DRQ, no error?	CP	08H	JR	NZ,BFAIL	LD	BC,0C8H		;256 bytes	INIR	INC	E	LD	A,E	CP	32	JR	NZ,BSAME	LD	E,0		;Next head	INC	DBSAME	LD	A,H	CP	24H		;Past 23FFH: on to the video memory	JR	NZ,BNOTV	LD	H,0F8HBNOTV	OR	A		;Wrapped round past FFFFH?	JR	NZ,BNEXT;;	As BOOT/SYS: disk driver hooks, memory map, CRTC;	LD	A,0C9H	LD	(FDDINT$),A	LD	HL,@RSTNMI	;NMI vector: SYSINIT only sets the	LD	(0067H),HL	;  address, BOOT/SYS puts the JP	LD	A,0C3H	LD	(0066H),A	LD	A,0FBH		;EI	LD	(DISKEI),A	LD	A,86H	LD	(OPREG$),A	LD	BC,15<8!88H	;Count, CRTC address register	LD	HL,CRTCTABBCRT	LD	A,(HL)	OUT	(C),B	OUT	(89H),A	DEC	HL	DEC	B	JP	P,BCRT	LD	SP,STACK$	JP	1E00H		;SYS0 (SYSINIT);BFAIL	LD	HL,BERRM	LD	DE,0FBE0H	;Middle of the screen	LD	BC,BERRE-BERRM	LDIR	JR	$BERRM	DB	'LS-DOS boot error'BERRE	IFGT	$,BOOT+256	ERR	'Loader too big'	ENDIF	END